def _timer_store_section_for_train_validation(
    section: Mapping[str, Any],
) -> dict[str, Any]:
    """Drop typed Redis placeholders without treating ``type`` as Redis-only.

    Train validation strips placeholders that
    :class:`~rasa.core.timer_stores.redis_timer_store.RedisSessionTimerStoreConfig`
    would reject (``port``, ``db``, …). That model's ``type`` is
    ``Literal["redis"]``, so ``type: ${TIMER_STORE}`` would also be stripped
    and then look like an omitted type (in-memory). A placeholder in ``type``
    is reported as a warning before this helper runs. Store selection belongs
    to :class:`~rasa.mantle.config.runtime_endpoints.TimerStoreSettings`, so
    ``type`` is always kept when it is a string constant.
    """
    # Imported lazily: the Redis client is unused for in-memory and custom stores.
    from rasa.core.timer_stores.redis_timer_store import RedisSessionTimerStoreConfig

    stripped = _without_typed_env_placeholders(section, RedisSessionTimerStoreConfig)
    if "type" in section:
        stripped["type"] = section["type"]
    return stripped


