def _literal_secret_warnings(
    section: Mapping[str, Any], section_name: str
) -> list[ValidationFinding]:
    """Warn when a secret field or a URL userinfo password is a literal.

    ``${VAR}`` placeholders and secrets-manager mappings are accepted without
    a warning. The finding names the key and never includes the value. Shared
    by the tracker store, the lock store, and the secrets manager. Dynamo
    access key id and secret access key are treated like a password.
    """
    findings: list[ValidationFinding] = []
    for key, value in section.items():
        if not isinstance(key, str):
            continue
        if key in _LITERAL_SECRET_FIELDS and _is_literal_secret(value):
            findings.append(
                _literal_secret_finding(
                    f"'{section_name}: {key}' in '{MANTLE_INTEGRATIONS_FILE}' "
                    "is a literal secret. Use a ${VAR} placeholder or a "
                    "secrets manager mapping ({source: secrets_manager.vault, "
                    "secret_key: ...})."
                )
            )
            continue
        if isinstance(value, str) and _url_embeds_literal_credentials(value):
            findings.append(
                _literal_secret_finding(
                    f"'{section_name}: {key}' in '{MANTLE_INTEGRATIONS_FILE}' "
                    "embeds credentials in a URL. Use a ${VAR} placeholder "
                    "instead of a user:password@ URL."
                )
            )
    return findings


def _is_literal_secret(value: Any) -> bool:
    """Test whether ``value`` is a secret written in the file itself."""
    if isinstance(value, Mapping):
        return False
    if not isinstance(value, str):
        return False
    return _ENV_PLACEHOLDER_PATTERN.search(value) is None


def _url_embeds_literal_credentials(value: str) -> bool:
    """Test whether ``value`` is a URL whose userinfo password is not ``${VAR}``."""
    match = _URL_USERINFO_PATTERN.search(value)
    if match is None:
        return False
    return _ENV_PLACEHOLDER_PATTERN.search(match.group(1)) is None


def _literal_secret_finding(message: str) -> ValidationFinding:
    """Build a non-blocking finding that does not repeat the secret value."""
    return ValidationFinding(
        code=_LITERAL_SECRET_CODE,
        severity="warning",
        message=message,
    )


def _type_env_placeholder_warning(
    section: Mapping[str, Any], section_name: str
) -> list[ValidationFinding]:
    """Warn when ``type`` is an environment variable instead of a constant.

    ``url`` and other connection fields may be ``${VAR}`` and are expanded at
    startup. ``type`` names a builtin or a class path; that choice is not a
    secret and is not expanded here.
    """
    type_value = section.get("type")
    if not isinstance(type_value, str) or not _ENV_PLACEHOLDER_PATTERN.search(
        type_value
    ):
        return []
    return [
        ValidationFinding(
            code=_TYPE_ENV_PLACEHOLDER_CODE,
            severity="warning",
            message=(
                f"'{section_name}: type' in '{MANTLE_INTEGRATIONS_FILE}' is "
                f"'{type_value}'. Environment variables in 'type' are not "
                "expanded; use a string constant. Some validation checks for "
                "this section were skipped because of this."
            ),
        )
    ]


def _validate_rasa_model_server_section(
    rasa_model_server_section: Any,
) -> list[ValidationFinding]:
    """Validate the optional ``rasa_model_server:`` section of ``integrations.yml``.

    This is the remote model server, not the ``models`` list inside a model
    group. Reuses :func:`~rasa.mantle.config.runtime_endpoints.parse_model_server`.
    ``${VAR}`` placeholders in typed fields such as ``wait_time_between_pulls``
    are not type-checked until startup. A missing section is valid (a local
    model or remote storage can be used instead).
    """
    if rasa_model_server_section is None:
        return []
    if not isinstance(rasa_model_server_section, Mapping):
        return [
            ValidationFinding(
                code=_INVALID_MODEL_SERVER_CODE,
                message=(
                    f"The 'rasa_model_server:' section of "
                    f"'{MANTLE_INTEGRATIONS_FILE}' must be a mapping with a 'url'. "
                    "This is the remote model server, not the 'models' list "
                    "inside a model group."
                ),
            )
        ]

    try:
        parse_model_server(
            _without_typed_env_placeholders(
                rasa_model_server_section, ModelServerSettings
            )
        )
    except RasaException as error:
        return [
            ValidationFinding(
                code=_INVALID_MODEL_SERVER_CODE,
                message=str(error),
            )
        ]
    return []


def _without_typed_env_placeholders(
    section: Mapping[str, Any], model: type[BaseModel]
) -> dict[str, Any]:
    """Drop ``${VAR}`` values whose field only accepts them once expanded.

    Train-time validation reads ``integrations.yml`` without expanding
    environment variables, so ``port: ${REDIS_PORT}`` is still the literal
    placeholder here, and an ``int`` field rejects it although startup accepts
    the expanded value. A placeholder is kept when ``model`` accepts it as is
    (string fields such as ``url``), so a required string field stays present.
    """
    return {
        key: value
        for key, value in section.items()
        if not _is_typed_env_placeholder(model, key, value)
    }


def _is_typed_env_placeholder(model: type[BaseModel], key: Any, value: Any) -> bool:
    """Test whether ``value`` is a placeholder that ``model.<key>`` rejects."""
    if not isinstance(value, str) or not _ENV_PLACEHOLDER_PATTERN.search(value):
        return False
    field = model.model_fields.get(key)
    if field is None:
        return False
    try:
        TypeAdapter(field.annotation).validate_python(value)
    except PydanticValidationError:
        return True
    return False


def _validate_mcp_servers_section(mcp_servers: Any) -> list[ValidationFinding]:
    """Validate the optional ``mcp_servers:`` section of ``integrations.yml``.

    Each entry is parsed with
    :class:`~rasa.mantle.config.integrations.MCPServerSpec` so train-time
    checks match the runtime loader shape (CALM list-of-named-records, auth
    folding, secret placeholders, optional ``meta_map`` / ``tool_timeout``).
    Server ``name``s must be unique. A missing section is valid (MCP servers
    are optional).
    """
    if mcp_servers is None:
        return []
    if not isinstance(mcp_servers, list):
        return [
            ValidationFinding(
                code=_INVALID_MCP_SERVER_CODE,
                message=(
                    f"The 'mcp_servers:' section of '{MANTLE_INTEGRATIONS_FILE}' "
                    "must be a list of server configurations."
                ),
            )
        ]

    findings: list[ValidationFinding] = []
    seen_names: set[str] = set()
    for index, entry in enumerate(mcp_servers):
        if not isinstance(entry, Mapping):
            findings.append(
                ValidationFinding(
                    code=_INVALID_MCP_SERVER_CODE,
                    message=(
                        f"MCP server at index {index} in "
                        f"'{MANTLE_INTEGRATIONS_FILE}' must be a mapping."
                    ),
                )
            )
            continue
        try:
            server = MCPServerSpec.model_validate(dict(entry))
        except PydanticValidationError as error:
            problems = _format_pydantic_errors(error, "mcp_servers")
            findings.append(
                ValidationFinding(
                    code=_INVALID_MCP_SERVER_CODE,
                    message=(
                        f"MCP server at index {index} in "
                        f"'{MANTLE_INTEGRATIONS_FILE}' is invalid: {problems}."
                    ),
                )
            )
            continue
        except RasaValidationError as error:
            findings.append(
                ValidationFinding(
                    code=_INVALID_MCP_SERVER_CODE,
                    message=(
                        f"MCP server at index {index} in "
                        f"'{MANTLE_INTEGRATIONS_FILE}' is invalid: {error}."
                    ),
                )
            )
            continue
        if server.name in seen_names:
            findings.append(
                ValidationFinding(
                    code="mantle.validation.config.duplicate_mcp_server_name",
                    message=(
                        f"Duplicate MCP server name '{server.name}' in "
                        f"'{MANTLE_INTEGRATIONS_FILE}'; names must be unique."
                    ),
                )
            )
        seen_names.add(server.name)
    return findings
